function validate([garbage, travel]) {
  if (garbage.length < 2 || garbage.length > 100000) return 'garbage needs 2 to 10^5 houses.';
  if (garbage.some(g => g.length < 1 || g.length > 10)) return 'Each house holds 1 to 10 units.';
  if (garbage.some(g => !/^[MPG]+$/.test(g))) return "Each house may only contain 'M', 'P' and 'G'.";
  if (travel.length !== garbage.length - 1) return 'travel must have one fewer entry than garbage.';
  if (travel.some(t => t < 1 || t > 100)) return 'Each travel time is between 1 and 100.';
  return null;
}

