function garbageCollection(garbage, travel) {
  const prefix = [0];
  for (let i = 0; i < travel.length; i++) {
    prefix.push(prefix[i] + travel[i]);
  }

  const last = { M: 0, P: 0, G: 0 };
  let total = 0;
  for (let i = 0; i < garbage.length; i++) {
    total += garbage[i].length;
    for (const type of garbage[i]) {
      last[type] = i;
    }
  }

  for (const type of ['M', 'P', 'G']) {
    total += prefix[last[type]];
  }
  return total;
}

