function garbageCollection(garbage, travel) {
  // Drive each truck house by house; travel is only paid when a later house has its kind.
  let minutes = 0;
  for (const type of 'MPG') {
    let pending = 0;
    for (let i = 0; i < garbage.length; i++) {
      if (i > 0) pending += travel[i - 1];
      const count = garbage[i].split('').filter(c => c === type).length;
      if (count > 0) {
        minutes += pending + count;
        pending = 0;
      }
    }
  }
  return minutes;
}

