function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? 1500 : int(2, 6);
  // Some inputs leave out a kind entirely, so its truck never moves.
  let kinds = ['M', 'P', 'G'].filter(() => rand() < 0.75);
  if (kinds.length === 0) kinds = ['G'];
  const maxLen = size === 'large' ? 8 : 4;
  const garbage = Array.from({ length: n }, () => Array.from({ length: int(1, maxLen) }, () => kinds[int(0, kinds.length - 1)]).join(''));
  const maxTravel = size === 'large' || rand() < 0.3 ? 100 : 10;
  const travel = Array.from({ length: n - 1 }, () => int(1, maxTravel));
  return [garbage, travel];
}
